#!/usr/bin/env python3
"""Lossless, standard-library-only file compression.

Usage: python3 compress.py input.txt output.bin
       python3 compress.py --decompress input.bin output.txt
"""
import argparse
import bz2
from pathlib import Path


def compress(data: bytes) -> bytes:
    return bz2.compress(data, compresslevel=9)


def decompress(data: bytes) -> bytes:
    return bz2.decompress(data)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--decompress', action='store_true')
    parser.add_argument('source', type=Path)
    parser.add_argument('destination', type=Path)
    args = parser.parse_args()
    operation = decompress if args.decompress else compress
    try:
        result = operation(args.source.read_bytes())
        args.destination.write_bytes(result)
    except (OSError, EOFError, ValueError) as exc:
        parser.exit(1, f'{parser.prog}: {exc}\n')


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Check the real CLI and repeatedly verify lossless compression before scoring."""
import subprocess
import sys
import time
from pathlib import Path


def score():
    root = Path(__file__).resolve().parent
    source = root / 'corpus.txt'
    packed = root / 'out.bin'
    restored = root / 'restored.txt'
    data = source.read_bytes()
    if not data:
        return 0.0
    for arguments in ([str(source), str(packed)],
                      ['--decompress', str(packed), str(restored)]):
        subprocess.run([sys.executable, str(root / 'compress.py'), *arguments],
                       check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if restored.read_bytes() != data:
        return 0.0
    encoded = packed.read_bytes()
    import compress
    start = time.perf_counter()
    while True:
        candidate = compress.compress(data)
        if candidate != encoded or compress.decompress(candidate) != data:
            return 0.0
        if time.perf_counter() - start >= 0.6:
            break
    return 100.0 * (1.0 - len(encoded) / len(data))


if __name__ == '__main__':
    try:
        value = score()
    except Exception:
        value = 0.0
    print(f'{value:.12f}')
